// ==========================
// 1. DEFINIÇÃO DOS TEMPLATES
// ==========================
const templates = {
  reminder_reuniao: {
    name: "reminder_reuniao",
    vars: 2,
    text: "Opa, {{1}}! Tudo certo por aí?\n\nEm 10 minutinhos a gente começa. Vou deixar o link aqui de novo pra facilitar:\n\n{{2}}\n\nAté já!"
  },

  reminder_reuniao_sem_link: {
    name: "reminder_reuniao_sem_link",
    vars: 1,
    text: "Oi, {{1}}! Tudo pronto aí?\n\nNossa reunião começa em *10 minutos*. Te aguardo!"
  },

  reminder_reuniao2: {
    name: "reminder_reuniao2",
    vars: 3,
    text: "Bom dia, {{1}}! Tudo bem?\n\nPassando só pra lembrar do nosso papo hoje às *{{2}}*.\n\nJá vou deixar o link aqui pra você se organizar:\n{{3}}\n\nCombinado? Até mais tarde!"
  },

  reminder_reuniao_sem_link2: {
    name: "reminder_reuniao_sem_link2",
    vars: 2,
    text: "Bom dia, {{1}}! Tudo bem?\n\nPassando pra lembrar da nossa reunião hoje às *{{2}}*.\n\nTudo certo pra gente conversar? Qualquer imprevisto me avisa!"
  },

  reminder_reuniao_amanha: {
    name: "reminder_reuniao_amanha",
    vars: 2,
    text: "Boa noite, {{1}}!\n\nSó passando pra deixar no radar nossa reunião de amanhã às *{{2}}*.\n\nPodemos manter confirmado? Abs!"
  }
};

// ==========================
// 2. DADOS DO LEAD
// ==========================
const origem = $('Preparar variáveis do lead').first().json;
const roteamento = $('Decide o agente').first().json;

// Evento encontrado no Calendar (ou null)
const evento = items.length ? items[0].json : null;

// Dados do lead
const name = origem.name || "Visitante";
const telefone = String(origem.telefone || "");
const motivo = origem.motivo;

// ==========================
// 3. LINK DA REUNIÃO
// ==========================
const linkReuniao =
    evento?.hangoutLink ||
    evento?.conferenceData?.entryPoints?.[0]?.uri ||
    evento?.location ||
    null;

// ==========================
// 4. HORÁRIO DA REUNIÃO
// ==========================
const horarioISO =
    evento?.start?.dateTime ??
    (origem.dt_call ? origem.dt_call.replace(" ", "T") : null);

let horarioFormatado = "";

if (horarioISO) {
    const dt = new Date(horarioISO);

    horarioFormatado = new Intl.DateTimeFormat("pt-BR", {
        timeZone: "America/Sao_Paulo",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false
    }).format(dt);
}

// ==========================
// 5. ESCOLHER TEMPLATE
// ==========================
let templateEscolhido;

switch (motivo) {

    case "reuniao_amanha":
        templateEscolhido = templates.reminder_reuniao_amanha;
        break;

    case "reuniao_hoje":
        templateEscolhido = linkReuniao
            ? templates.reminder_reuniao2
            : templates.reminder_reuniao_sem_link2;
        break;

    case "reuniao_proximos_10min":
    default:
        templateEscolhido = linkReuniao
            ? templates.reminder_reuniao
            : templates.reminder_reuniao_sem_link;
}

// ==========================
// 6. PARAMETERS
// ==========================
const parameters = [];

// {{1}}
parameters.push({
    type: "text",
    text: name
});

if (motivo === "reuniao_amanha") {

    // {{2}} horário
    parameters.push({
        type: "text",
        text: horarioFormatado
    });

} else if (motivo === "reuniao_hoje") {

    // {{2}}
    parameters.push({
        type: "text",
        text: horarioFormatado
    });

    // {{3}}
    if (linkReuniao) {
        parameters.push({
            type: "text",
            text: linkReuniao
        });
    }

} else {

    // 10 minutos
    if (linkReuniao) {
        parameters.push({
            type: "text",
            text: linkReuniao
        });
    }
}

// ==========================
// 7. BODY WHATSAPP
// ==========================
const body = {
    messaging_product: "whatsapp",
    to: telefone,
    type: "template",
    template: {
        name: templateEscolhido.name,
        language: {
            code: "pt_BR"
        },
        components: [
            {
                type: "body",
                parameters
            }
        ]
    }
};

// ==========================
// 8. TEXTO SIMULADO
// ==========================
let textoSimulado = templateEscolhido.text;

textoSimulado = textoSimulado.replace("{{1}}", name);

if (motivo === "reuniao_amanha") {

    textoSimulado = textoSimulado.replace("{{2}}", horarioFormatado);

} else if (motivo === "reuniao_hoje") {

    textoSimulado = textoSimulado.replace("{{2}}", horarioFormatado);

    if (linkReuniao) {
        textoSimulado = textoSimulado.replace("{{3}}", linkReuniao);
    }

} else {

    if (linkReuniao) {
        textoSimulado = textoSimulado.replace("{{2}}", linkReuniao);
    }
}

textoSimulado = textoSimulado.replace(/{{[0-9]+}}/g, "");

// ==========================
// 9. REDIS CHAT MEMORY
// ==========================
const redisMemoryMessage = JSON.stringify({
    type: "ai",
    data: {
        content: textoSimulado,
        tool_calls: [],
        invalid_tool_calls: [],
        additional_kwargs: {},
        response_metadata: {},
    },
});

// ==========================
// RETORNO
// ==========================
return [{
    json: {
        // Body da API da Meta
        resultado_api: body,

        // Texto renderizado (útil para logs)
        mensagem_visual: textoSimulado,

        // Compatível com Redis Chat Memory
        mensagem_para_historico: textoSimulado,
        redis_memory_message: redisMemoryMessage,

        // Dados auxiliares
        template_name: templateEscolhido.name,
        motivo_disparo: motivo,
        lead_nome: name,
        lead_telefone: telefone,
        link_encontrado: !!linkReuniao,
        evento_calendar: evento?.id || null,

        // Roteamento do agente
        agente: roteamento.agente,
        nome_app: roteamento.nome_app,
        phone_number_id: roteamento.phone_number_id,
        origem_decisao: roteamento.origem_decisao
    }
}];

function ajustarTelefone(raw) {
  if (!raw) return null;
  let t = raw.toString().replace(/\D/g, "");
  if (t.length === 11) t = "55" + t;
  if (t.length === 10) t = "55" + t;
  if (t.startsWith("55")) return t;
  if (t.startsWith("+")) return t.replace("+", "");
  return t;
}

// Brasil não tem mais horário de verão desde 2019, então o offset é sempre -3h fixo
const BRASILIA_OFFSET_HOURS = 3;

// Converte "2026-07-22 09:30:00" (horário de Brasília) -> Date UTC correto,
// independente do timezone do container onde o n8n roda (aqui, UTC).
function parseDtCall(dtCallStr) {
  if (!dtCallStr) return null;
  const [dataPart, horaPart] = dtCallStr.split(" ");
  if (!dataPart) return null;
  const [ano, mes, dia] = dataPart.split("-").map(Number);
  const [h, m, s] = (horaPart || "00:00:00").split(":").map(Number);
  return new Date(Date.UTC(ano, mes - 1, dia, (h || 0) + BRASILIA_OFFSET_HOURS, m || 0, s || 0));
}

// Retorna a data (YYYY-MM-DD) de "hoje" ou "amanhã" no fuso de Brasília,
// calculada a partir do timestamp UTC atual (não usa toISOString() puro,
// que pegaria o dia em UTC e erraria perto da meia-noite de Brasília).
function dataBrasiliaISO(offsetDias = 0) {
  const agoraUTC = Date.now();
  const brt = new Date(agoraUTC - BRASILIA_OFFSET_HOURS * 60 * 60 * 1000);
  brt.setUTCDate(brt.getUTCDate() + offsetDias);
  return brt.toISOString().split("T")[0];
}

// ========================================
// Identificar gatilho real (9h ou 10min)
// ========================================
let gatilho = null;
try { gatilho = $('Seta o gatilho').first().json.gatilho || null; } catch {}
try { gatilho = $('Seta o gatilho1').first().json.gatilho || gatilho; } catch {}
try { gatilho = $('Seta o gatilho2').first().json.gatilho || gatilho; } catch {}
if (!gatilho) {
  gatilho = "10min";
}

const filtrados = [];

// ========================================================
// CASO 0 → Execução das 19h (Lembrete do dia anterior)
// ========================================================
if (gatilho === "19h") {
  const dataAmanha = dataBrasiliaISO(1);

  for (const item of items) {
    const lead = item.json;
    const telefone = lead.telefone || lead.whatsapp;
    const reuniao = lead.dt_call;
    if (!reuniao) continue;

    const dataReuniao = reuniao.split(" ")[0]; // YYYY-MM-DD
    if (dataReuniao === dataAmanha) {
      filtrados.push({
        json: {
          ...lead,
          telefonePadronizado: ajustarTelefone(telefone),
          motivo: "reuniao_amanha"
        }
      });
    }
  }
  return filtrados;
}

// ========================================
// CASO 1 → Execução das 9h (gatilho = "9h")
// ========================================
if (gatilho === "9h") {
  const hoje = dataBrasiliaISO(0);

  for (const item of items) {
    const lead = item.json;
    const telefone = lead.telefone || lead.whatsapp;
    const reuniao = lead.dt_call;
    if (!reuniao) continue;

    const dataReuniao = reuniao.split(" ")[0];
    if (dataReuniao === hoje) {
      filtrados.push({
        json: {
          ...lead,
          telefonePadronizado: ajustarTelefone(telefone),
          motivo: "reuniao_hoje"
        }
      });
    }
  }
  return filtrados;
}

// ========================================
// CASO 2 → Execução dos 21/51 min (10 min antes)
// ========================================
const agoraUTC = Date.now();
const min7 = agoraUTC + 7 * 60 * 1000;
const min12 = agoraUTC + 12 * 60 * 1000;

for (const item of items) {
  const lead = item.json;
  const telefone = lead.telefone || lead.whatsapp;
  const reuniao = lead.dt_call;
  if (!reuniao) continue;

  const dataObj = parseDtCall(reuniao);
  if (!dataObj) continue;
  const timestampReuniao = dataObj.getTime();

  if (timestampReuniao >= min7 && timestampReuniao <= min12) {
    filtrados.push({
      json: {
        ...lead,
        telefonePadronizado: ajustarTelefone(telefone),
        motivo: "reuniao_proximos_10min"
      }
    });
  }
}
return filtrados;

// Dados do lead
const lead = $('Preparar variáveis do lead').first().json;

const emailLead = (lead.email || "").trim().toLowerCase();

// "2026-07-24 11:30:00" -> "2026-07-24T11:30:00"
const dtLead = (lead.dt_call || "").replace(" ", "T");

for (const item of items) {
  const evento = item.json;

  const inicio = evento.start?.dateTime;
  if (!inicio) continue;

  // Remove timezone para comparar apenas data/hora
  const inicioSemTZ = inicio.substring(0, 19);

  if (inicioSemTZ !== dtLead) continue;

  // Verifica se o e-mail está entre os convidados
  const participantes = evento.attendees || [];

  const encontrouEmail = participantes.some(
    p => (p.email || "").toLowerCase() === emailLead
  );

  if (!encontrouEmail) continue;

  return [
    {
      json: {
        ...evento,
        tem_call: true
      }
    }
  ];
}

// Não encontrou
return [
  {
    json: {
      tem_call: false
    }
  }
];

// =====================================================================
// Decide QUAL agente (numero) deve disparar o reminder para este lead.
//
// Prioridade:
//   1. nome_app da ultima mensagem no historico (fonte de verdade)
//   2. midia_id do mailing
//      15 = remarketing
//      14 = inbound
//       2 = parceiros
//   3. default = inbound
// =====================================================================

const lead = $('Preparar variáveis do lead').first().json;

const AGENTES = {
  inbound: {
    agente: 'inbound',
    nome_app: 'SDR-INBOUND',
    phone_number_id: '1292568043938721',
    whatsapp_business_id: '1540465040616348',
    redis_suffix: '_mem_agent_FINAMOB_SDR_INBOUND'
  },

  remarketing: {
    agente: 'remarketing',
    nome_app: 'SDR-REMARKETING',
    phone_number_id: '1202871396233612',
    whatsapp_business_id: '1017599083929094',
    redis_suffix: '_mem_agent_FINAMOB_SDR'
  },

  parceiros: {
    agente: 'parceiros',
    nome_app: 'SDR-PARCEIROS',
    phone_number_id: '1374636505725573',
    whatsapp_business_id: '1080464844460481',
    redis_suffix: '_mem_agent_FINAMOB_SDR_PARCEIROS'
  }
};


// ---- 1. Histórico ---------------------------------------------------
let origem = 'historico';
let escolhido = null;

const hist = items && items.length ? items[0].json : null;

const nomeAppHist = hist && hist.nome_app
  ? String(hist.nome_app).trim().toUpperCase()
  : null;

if (nomeAppHist === 'SDR-REMARKETING') {
  escolhido = AGENTES.remarketing;

} else if (nomeAppHist === 'SDR-INBOUND') {
  escolhido = AGENTES.inbound;

} else if (nomeAppHist === 'SDR-PARCEIROS') {
  escolhido = AGENTES.parceiros;
}


// ---- 2. midia_id ----------------------------------------------------
if (!escolhido) {
  origem = 'midia_id';

  const midia = String(lead.midia_id ?? '').trim();

  if (midia === '15') {
    escolhido = AGENTES.remarketing;

  } else if (midia === '14') {
    escolhido = AGENTES.inbound;

  } else if (midia === '2') {
    escolhido = AGENTES.parceiros;
  }
}


// ---- 3. Default -----------------------------------------------------
if (!escolhido) {
  origem = 'default_inbound';
  escolhido = AGENTES.inbound;
}


// ---- Retorno --------------------------------------------------------
return [{
  json: {
    ...escolhido,
    origem_decisao: origem,
    nome_app_historico: nomeAppHist,
    midia_id: lead.midia_id ?? null,
    telefone: lead.telefone,
    lead_nome: lead.name
  }
}];

